import{_ as c,C as o,o as a,c as l,a2 as t,b as s,w as r,a as d,E as A,a3 as n}from"./chunks/framework.DZUUNQ77.js";const v=JSON.parse('{"title":"AttributeCache · 窗口属性缓存","description":"","frontmatter":{},"headers":[],"relativePath":"reference/server/am-classes/attribute-cache.md","filePath":"reference/server/am-classes/attribute-cache.md","lastUpdated":1784053534000}'),E={name:"reference/server/am-classes/attribute-cache.md"};function h(u,e,p,m,C,b){const i=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="attributecache-·-窗口属性缓存" tabindex="-1">AttributeCache · 窗口属性缓存 <a class="header-anchor" href="#attributecache-·-窗口属性缓存" aria-label="Permalink to &quot;AttributeCache · 窗口属性缓存&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/server/am/AttributeCache.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/server/am/AttributeCache.java</code></a></p></div><p><code>AttributeCache</code> 对应 AOSP 同名类，缓存 <code>WindowManager.LayoutParams</code> 相关的窗口属性查询结果，避免每次启动 Activity 都跨进程向真实 WindowManager 查窗口属性（主题、尺寸、动画等），减少 IPC 开销。</p><h2 id="缓存结构" tabindex="-1">缓存结构 <a class="header-anchor" href="#缓存结构" aria-label="Permalink to &quot;缓存结构&quot;">​</a></h2><p>按 <code>(packageName, resId)</code> 二级索引缓存窗口属性集合：</p><ul><li>一级键：包名（虚拟 App）。</li><li>二级键：<code>windowAnimationStyle</code> 等 <code>resId</code>。</li><li>值：解析出的窗口属性对象。</li></ul><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p><code>ActivityStack</code> 启动 Activity 时要查窗口属性配置主题和动画。这些属性在 App 的 resources 里，需要跨进程从虚拟 App 的资源加载器取。<code>AttributeCache</code> 把首次查询结果缓存，后续相同 (包名, resId) 直接命中，避免重复 IPC 与资源解析。</p><h2 id="失效" tabindex="-1">失效 <a class="header-anchor" href="#失效" aria-label="Permalink to &quot;失效&quot;">​</a></h2><p>App 升级或资源配置变化时缓存失效，由 <a href="./../pm"><code>VPackageManagerService</code></a> 在包变更时通知清理对应条目。</p><h2 id="缓存查询流" tabindex="-1">缓存查询流 <a class="header-anchor" href="#缓存查询流" aria-label="Permalink to &quot;缓存查询流&quot;">​</a></h2>',11)),(a(),s(n,null,{default:r(()=>[A(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20LR%0A%20%20AS%5B%22ActivityStack%3Cbr%2F%3E%E5%90%AF%E5%8A%A8%20Activity%22%5D%20--%3E%20Q%5B%22%E6%9F%A5%E7%AA%97%E5%8F%A3%E5%B1%9E%E6%80%A7%3Cbr%2F%3E(pkg%2C%20resId)%22%5D%0A%20%20Q%20--%3E%20CACHE%7B%22AttributeCache%3Cbr%2F%3E%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20CACHE%20--%3E%7C%22%E6%98%AF%22%7C%20HIT%5B%22%E8%BF%94%E5%9B%9E%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%7C%22%E5%90%A6%22%7C%20MISS%5B%22%E8%B7%A8%E8%BF%9B%E7%A8%8B%E6%9F%A5%E8%B5%84%E6%BA%90%22%5D%0A%20%20MISS%20--%3E%20STORE%5B%22%E8%A7%A3%E6%9E%90%20%2B%20%E5%AD%98%E5%85%A5%E7%BC%93%E5%AD%98%22%5D%0A%20%20STORE%20--%3E%20HIT%0A%20%20HIT%20--%3E%20AS%0A%20%20VPMS%5B%22VPackageManagerService%3Cbr%2F%3E%E5%8C%85%E5%8F%98%E6%9B%B4%22%5D%20-.-%3E%7C%22%E5%A4%B1%E6%95%88%22%7C%20CACHE%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./../am"><code>VActivityManagerService</code></a>：<code>ActivityStack</code> 使用方。</li><li><a href="./../pm"><code>VPackageManagerService</code></a>：包变更触发缓存失效。</li><li><a href="/VirtualXposed-skills/features/activity-manager">活动管理</a>。</li></ul>',2))])}const f=c(E,[["render",h]]);export{v as __pageData,f as default};
